from pathlib import Path
import json,hashlib,zipfile
from PIL import Image,ImageOps
root=Path(__file__).resolve().parent
langs=['es','en','pt-BR']
def save(name,obj): (root/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
p=json.loads((root/'paquete-preprod.json').read_text())
old={x['slug']:x for x in p['places']}
refs=json.loads((root/'referencias-v4.json').read_text())
for r in refs:
 im=ImageOps.exif_transpose(Image.open(root/r['original_path'])).convert('RGB');r['downloaded_dimensions']=list(im.size)
 im.thumbnail((1800,1200) if r['id'].startswith('portada-') else (1000,800))
 name='v4-'+r['id']+'.webp';target=root/'imagenes'/name
 im.save(target,'WEBP',quality=82,method=6)
 r['derivative_path']='imagenes/'+name;r['derivative_sha256']=hashlib.sha256(target.read_bytes()).hexdigest();r['derivative_dimensions']=list(im.size)
 r['visual_review']=json.loads((root/'revision-visual-v4.json').read_text())['review'].get(r['id'],'pending_local_inspection');r['transformations']='EXIF orientation, proportional resize without crop, WebP82, metadata stripped; technical preview only'
assets={r['id']:r for r in refs}
def asset(id,alt):
 r=assets[id]
 return {'file':'images/v4-'+id+'.webp','image_origin':'external','image_creator':r['author'],'image_source_url':r['source_page'],'image_license':r['license'],'image_license_url':r['license_url'],'alt':dict(zip(langs,alt)),'caption':{l:r['author']+' / Wikimedia Commons / '+r['license'] for l in langs}}
p['hero_image']=asset('portada-camellon',['Vista aérea del Camellón de la Bahía y el frente urbano de Santa Marta, fotografía de 2022','Aerial view of the bay promenade and Santa Marta waterfront, photograph from 2022','Vista aérea do calçadão da baía e da orla urbana de Santa Marta, fotografia de 2022'])
# Selection is editorial relevance, independent from availability of a photograph.
data=[
 ('tayrona',['Parque Nacional Natural Tayrona','Tayrona National Natural Park','Parque Nacional Natural Tayrona'],['Senderos entre bosque tropical, rocas y playas como Cabo San Juan. El parque pertenece al distrito de Santa Marta; consulta accesos, cierres y zonas habilitadas con Parques Nacionales antes de organizar una excursión.','Trails through tropical forest, rock formations and beaches such as Cabo San Juan. The park lies within Santa Marta district; check entry points, closures and authorised areas with National Parks before planning a trip.','Trilhas entre floresta tropical, rochas e praias como Cabo San Juan. O parque fica no distrito de Santa Marta; consulte acessos, fechamentos e áreas autorizadas com Parques Nacionais antes do passeio.'],'https://old.parquesnacionales.gov.co/portal/especial/tayrona/','tayrona',['Cabo San Juan en el Tayrona, fotografía de 2014','Cabo San Juan in Tayrona, photograph from 2014','Cabo San Juan no Tayrona, fotografia de 2014']),
 ('quinta',['Quinta de San Pedro Alejandrino']*3,['La casa donde murió Simón Bolívar en 1830 permite conectar historia, museo y jardines. Es una visita cultural dentro de Santa Marta, diferente del paseo por su centro histórico.','The house where Simón Bolívar died in 1830 brings together history, a museum and gardens. This cultural visit within Santa Marta complements a walk through the historic centre.','A casa onde Simón Bolívar morreu em 1830 reúne história, museu e jardins. Esta visita cultural em Santa Marta complementa o passeio pelo centro histórico.'],'https://www.museobolivariano.org.co/laquinta/',None,None),
 ('centro-historico',['Centro histórico y Catedral','Historic centre and Cathedral','Centro histórico e Catedral'],['Recorre las calles del centro, la Catedral y el entorno del Parque de los Novios. Combina arquitectura, plazas y vida urbana en un paseo que puedes continuar hacia el malecón.','Walk through the centre, past the Cathedral and around Parque de los Novios. Architecture, squares and urban life share a route that you can continue towards the waterfront.','Percorra as ruas do centro, a Catedral e os arredores do Parque de los Novios. Arquitetura, praças e vida urbana se encontram neste passeio, que pode seguir até a orla.'],'https://colombia.travel/es/santa-marta',None,None),
 ('taganga',['Taganga']*3,['Bahía, embarcaciones de pesca y miradores costeros dan identidad a este corregimiento de Santa Marta. Dedica tiempo a su paisaje y ambiente pesquero, distintos de El Rodadero; consulta las condiciones de las salidas de buceo con sus operadores.','The bay, fishing boats and coastal viewpoints define this rural district of Santa Marta. Take time to enjoy its scenery and fishing character, distinct from El Rodadero; check diving arrangements with the operators.','A baía, os barcos de pesca e os mirantes costeiros definem este corregimiento de Santa Marta. Dedique tempo à paisagem e ao ambiente pesqueiro, diferentes de El Rodadero; consulte as condições dos mergulhos com os operadores.'],'https://colombia.travel/es/santa-marta',None,None),
 ('rodadero',['El Rodadero']*3,['Playa urbana y paseo costero en la bahía de Gaira, con un ambiente distinto al centro y a Taganga. Es un sector de Santa Marta, con identidad turística propia y opciones para organizar salidas por mar.','An urban beach and waterfront on Gaira Bay, with a character different from downtown and Taganga. This area of Santa Marta has its own tourism identity and serves as a starting point for sea outings.','Praia urbana e passeio à beira-mar na baía de Gaira, com ambiente diferente do centro e de Taganga. Este setor de Santa Marta tem identidade turística própria e serve de ponto de partida para passeios marítimos.'],'https://colombia.travel/es/santa-marta','rodadero',['Vista de la playa de El Rodadero, fotografía de 2012','View of El Rodadero beach, photograph from 2012','Vista da praia de El Rodadero, fotografia de 2012']),
 ('minca',['Minca']*3,['Este corregimiento en las estribaciones de la Sierra Nevada ofrece paisaje de montaña, café y observación de aves. Planéalo como una salida desde la ciudad y conserva su identidad propia: no es otro municipio ni una playa de Santa Marta.','This rural district in the Sierra Nevada foothills offers mountain scenery, coffee and birdwatching. Plan it as a trip from the city while keeping its distinct identity: it is neither a separate municipality nor a Santa Marta beach.','Este corregimiento nos contrafortes da Sierra Nevada oferece paisagem de montanha, café e observação de aves. Planeje uma saída da cidade preservando sua identidade: não é outro município nem uma praia de Santa Marta.'],'https://colombia.travel/es/santa-marta/descanso-en-minca','minca',['Paisaje de Minca desde el camino a La Candelaria, fotografía de 2016','Minca landscape from the path to La Candelaria, photograph from 2016','Paisagem de Minca no caminho a La Candelaria, fotografia de 2016']),
 ('museo-tairona',['Museo del Oro Tairona · Casa de la Aduana','Tairona Gold Museum · Customs House','Museu do Ouro Tairona · Casa da Aduana'],['La Casa de la Aduana reúne patrimonio arqueológico y relatos sobre las sociedades de la Sierra Nevada y Santa Marta. Aporta contexto cultural al viaje más allá de las playas y la memoria colonial.','The Customs House brings together archaeological heritage and stories about the societies of the Sierra Nevada and Santa Marta. It adds cultural context beyond beaches and colonial history.','A Casa da Aduana reúne patrimônio arqueológico e relatos sobre as sociedades da Sierra Nevada e de Santa Marta. Acrescenta contexto cultural à viagem além das praias e da história colonial.'],'https://www.santamarta.gov.co/museos','museo-tairona',['Fachada de la Casa de la Aduana en Santa Marta, fotografía de 2024','Facade of the Customs House in Santa Marta, photograph from 2024','Fachada da Casa da Aduana em Santa Marta, fotografia de 2024']),
 ('acuario',['Acuario y Museo del Mar de El Rodadero','El Rodadero Aquarium and Sea Museum','Aquário e Museu do Mar de El Rodadero'],['Espacio de visita dedicado a fauna marina en el entorno costero de El Rodadero, al que se llega por mar. No es el Acuario Mundo Marino: son establecimientos diferentes. Consulta directamente condiciones de acceso y programa de visita.','A visitor venue devoted to marine fauna on the coast near El Rodadero, reached by sea. It is separate from Acuario Mundo Marino. Check access arrangements and the visitor programme directly with the venue.','Espaço de visita dedicado à fauna marinha no litoral próximo de El Rodadero, com acesso pelo mar. É diferente do Acuario Mundo Marino. Consulte diretamente as condições de acesso e o programa de visita.'],'https://apropiaconsentido.minciencias.gov.co/donde-estamos-3/','acuario',['Instalaciones del Acuario El Rodadero con delfines, fotografía histórica de 2011','El Rodadero Aquarium facilities with dolphins, historical photograph from 2011','Instalações do Aquário El Rodadero com golfinhos, fotografia histórica de 2011'])]
places=[]
for slug,names,descs,url,img,alts in data:
 image=asset(img,alts) if img else old[slug if slug in old else {'centro-historico':'catedral'}.get(slug,slug)]['image']
 places.append(dict(slug=slug,type='place',publication_status='draft',translations={l:dict(name=names[i],description=descs[i],external_url=url,external_label=['Fuente oficial','Official source','Fonte oficial'][i]) for i,l in enumerate(langs)},image=image))
p['places']=places
intros=['El Caribe se encuentra con la Sierra Nevada en un distrito que reúne centro histórico, playas y montaña. Explora cada zona a su ritmo: Taganga, El Rodadero, Minca y Tayrona tienen paisajes e identidades diferentes.','The Caribbean meets the Sierra Nevada in a district combining a historic centre, beaches and mountains. Explore each area at its own pace: Taganga, El Rodadero, Minca and Tayrona have different landscapes and identities.','O Caribe encontra a Sierra Nevada em um distrito que reúne centro histórico, praias e montanha. Explore cada área no seu ritmo: Taganga, El Rodadero, Minca e Tayrona têm paisagens e identidades diferentes.']
for i,l in enumerate(langs):
 p['destination']['translations'][l].update(headline=['Santa Marta, entre el Caribe y la Sierra','Santa Marta, between the Caribbean and the Sierra','Santa Marta, entre o Caribe e a Sierra'][i],intro=intros[i],eyebrow=['PREPROD · Referencias por aprobar','PREPROD · References pending approval','PREPROD · Referências pendentes de aprovação'][i],meta_description=intros[i][:155])
 p['destination']['history'][l][-1]=p['destination']['history'][l][-1].split([' La fotografía',' The same',' A mesma'][i])[0]
p['destination']['reasons']={l:rs for l,rs in zip(langs,[['Combina playas caribeñas y montaña.','Recorre historia, patrimonio y vida urbana.','Conoce bahías con identidad propia.','Descubre el café y las aves de la Sierra.'],['Combine Caribbean beaches and mountains.','Explore history, heritage and urban life.','Visit bays with their own identities.','Discover the Sierra’s coffee and birdlife.'],['Combine praias caribenhas e montanha.','Explore história, patrimônio e vida urbana.','Conheça baías com identidade própria.','Descubra o café e as aves da Sierra.']])}
p['local_research']['notes']=['Selección de ocho principales por relevancia y variedad; inventario amplio preservado en revision-ampliada.json.','Taganga y Minca: corregimientos del distrito. El Rodadero: sector urbano. Mantener guías autónomas relacionadas sin doble conteo.','Fotografías históricas de referencia no aprobadas; generación con skill después de elección humana.','Acuario Rodadero y Acuario Mundo Marino son distintos. Foto acuario2011 provisional, mejorar encuadre sin espectáculo.','Historia: imagen independiente pendiente; no reutilizar automáticamente portada/tarjetas.']
sources=[dict(label='Parques Nacionales · ubicación Tayrona',url='https://old.parquesnacionales.gov.co/portal/especial/tayrona/',section_key='history'),dict(label='ProColombia · Minca',url='https://colombia.travel/es/santa-marta/descanso-en-minca',section_key='history'),dict(label='MinCiencias · Acuario Rodadero',url='https://apropiaconsentido.minciencias.gov.co/donde-estamos-3/',section_key='history'),dict(label='Mundo Marino · distinción de acuarios',url='https://mundomarinoacuario.com.co/preguntas-frecuentes/',section_key='history')]
for l in langs:p['destination']['sources'][l].extend([s for s in sources if s['url'] not in {e['url'] for e in p['destination']['sources'][l]}])
history=asset('historia-aduana',['Fachada histórica de la Casa de la Aduana, fotografía de 2009','Historic facade of the Customs House, photograph from 2009','Fachada histórica da Casa da Aduana, fotografia de 2009'])
history['file']='images/santa-marta-history.webp'
historybytes=(root/'imagenes/v4-historia-aduana.webp').read_bytes()
(root/'santa-marta-history.webp').write_bytes(historybytes)
save('santa-marta-history.json',{'destination':'santa-marta','image':history,'sha256':hashlib.sha256(historybytes).hexdigest(),'approval':'pending','purpose':'Separate history reference: Customs House colonial heritage; external facade different from museum card photograph2024'})
p['local_research']['notes'][-1]='Historia: referencia propia Casa de la Aduana exterior, distinta de portada y tarjetas; sidecar local separado del ZIPv2.'
save('paquete-preprod.json',p);save('referencias-v4.json',refs)
with zipfile.ZipFile(root/'paquete-preprod.zip','w',zipfile.ZIP_DEFLATED) as z:
 z.write(root/'paquete-preprod.json','paquete-destino.json')
 for image in [p['hero_image']]+[x['image'] for x in places]:
  z.write(root/'imagenes'/Path(image['file']).name,image['file'])
# All generated text previews reflect the same final package, preserving historical files through git.
for l in langs:
 t=p['destination']['translations'][l]
 text='# '+t['headline']+'\n\n'+t['intro']+'\n\n## '+{'es':'Historia','en':'History','pt-BR':'História'}[l]+'\n\n'+'\n\n'.join(p['destination']['history'][l])+'\n\n'
 for x in places:text+='## '+x['translations'][l]['name']+'\n\n'+x['translations'][l]['description']+'\n\n'
 (root/('texto-'+l.lower()+'.md')).write_text(text)
report=dict(destination='santa-marta',revision='v4',places=8,images=10,package_images=9,history_images=1,history_sidecar='santa-marta-history.json',distinct_image_source_urls=len({i['image_source_url'] for i in [p['hero_image']]+[x['image'] for x in places]}),provisional=True,final_ai_images=0,production_authorized=False,preprod_imported=False,missing=['Aprobar referencias una por una','Mejorar referencia acuario: histórica2011, espectáculo no representa toda visita','Generar y aprobar ilustraciones finales con skill','Completar actividades y directorio','Validación visual tras importación coordinador'])
save('reporte-preprod.json',report)
print(json.dumps(report,ensure_ascii=False))
